{
  "outcome": "deny",
  "rationale": "We are denying this claim because the insured admitted to intentionally crashing the vehicle, which triggers the policy's intentional acts exclusion. Section [STD-4.3] clearly states that the insurer does not cover loss caused intentionally by an insured person. The key fact is that the claimant deliberately steered her car into a concrete barrier.",
  "citations": [
    {
      "clause_id": "STD-4.3",
      "quote": "We do not cover loss caused intentionally by, or at the direction of, an insured person."
    }
  ]
}
